-- A CapsuleBin 1.0 database, as SQLite's .dump writes it. Read by tests/upgrade.rs.
--
-- Written by the 1.0 binary itself (`serve`, then `moderation disable` and
-- `reports close`), so `_sqlx_migrations` carries the checksums 1.0 recorded.
-- Never regenerate or edit it: it stands for databases already in the field.
--
--   EBAQEBAQEBAQEBAQEBAQEA  active; tokens describe-10, reveal-10, delete-10
--   EREREREREREREREREREREQ  burn after retrieval, already retrieved (tombstone)
--   EhISEhISEhISEhISEhISEg  password header; tokens describe-12, reveal-12, delete-12
--   ExMTExMTExMTExMTExMTEw  disabled by moderation (spam); tokens describe-13, reveal-13;
--                           one report about it, closed with action_taken
--
-- The ciphertext of paste NN is 0x00 0xFF followed by "fixture-ciphertext-NN".
BEGIN TRANSACTION;
CREATE TABLE _sqlx_migrations (
    version BIGINT PRIMARY KEY,
    description TEXT NOT NULL,
    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    success BOOLEAN NOT NULL,
    checksum BLOB NOT NULL,
    execution_time BIGINT NOT NULL
);
INSERT INTO "_sqlx_migrations" VALUES(1,'init','2026-11-19 06:52:54',1,X'ED6A9115B5C4BAD4516496F55F16AF4A487A2DA6A9464157B672041A1D947ABD5A7440379D85EC5FFCFB5F00A039A439',433807);
INSERT INTO "_sqlx_migrations" VALUES(2,'describe verifier','2026-11-19 06:52:54',1,X'7D25D54874402CB1AF6564E5D691E7B50E5FA123BE342A1CF8C6E81F6848D21B88D6549DDE8E40ABF027600A77E5176B',197989);
INSERT INTO "_sqlx_migrations" VALUES(3,'drop retrieval count','2026-11-19 06:52:54',1,X'CCDE420E087C08CBBCB322D1E08952D592A131A94ABDC023B86D9CFBDFA33363CA3BBF7263B44D7655875F230FEEF54E',457507);
CREATE TABLE abuse_reports (
    id                    TEXT PRIMARY KEY,
    paste_id              TEXT NOT NULL,
    reason_code           TEXT NOT NULL,
    description           TEXT NOT NULL,
    reporter_contact      TEXT,
    created_at            INTEGER NOT NULL,
    status                TEXT NOT NULL DEFAULT 'open'
                          CHECK (status IN ('open','reviewing','closed')),
    handled_at            INTEGER,
    resolution            TEXT
);
INSERT INTO "abuse_reports" VALUES('01M7S98SY7CGG79GVHXS6R3ZBQ','ExMTExMTExMTExMTExMTEw','spam','fixture report','reporter@example.org',1795071174,'closed',1795071174,'action_taken');
CREATE TABLE moderation_actions (
    id                    INTEGER PRIMARY KEY AUTOINCREMENT,
    paste_id              TEXT NOT NULL,
    action                TEXT NOT NULL,
    reason_code           TEXT,
    note                  TEXT,
    created_at            INTEGER NOT NULL
);
INSERT INTO "moderation_actions" VALUES(1,'ExMTExMTExMTExMTExMTEw','disable','spam','fixture',1795071174);
CREATE TABLE pastes (
    id                    TEXT PRIMARY KEY,
    format_version        INTEGER NOT NULL,
    public_header         BLOB NOT NULL,
    ciphertext            BLOB,
    reveal_verifier       BLOB NOT NULL,
    delete_verifier       BLOB NOT NULL,
    created_at            INTEGER NOT NULL,
    last_retrieved_at     INTEGER,
    expires_at            INTEGER,
    burn_after_retrieval  INTEGER NOT NULL DEFAULT 0
                          CHECK (burn_after_retrieval IN (0, 1)),
    consumed_at           INTEGER,
    payload_size          INTEGER NOT NULL,
    availability_status   TEXT NOT NULL DEFAULT 'active'
                          CHECK (availability_status IN ('active','disabled','deleted')),
    moderation_reason     TEXT,
    moderated_at          INTEGER
, describe_verifier BLOB);
